<?php $uiTitle='Daftar Tugas';$uiPage='view-tasks';require __DIR__.'/../ui_head.php'; ?>
<main class="ui-container student-container">
 <section class="ui-page-heading task-heading"><div><span class="eyebrow teal"><?= uiIcon('clipboard',16) ?> AKADEMIK SEMESTER <?= date('n') <=6 ? 'GENAP' : 'GANJIL' ?></span><h1>Daftar Tugas</h1><p>Tugas yang harus dikerjakan dan dikumpulkan.</p></div><div class="task-counters"><span><i class="status-dot red"></i><b><?= $belumSelesai ?></b> Menunggu</span><i></i><span><i class="status-dot"></i><b><?= $sudahSelesai ?></b> Selesai</span></div></section>
 <div class="ui-toolbar"><nav class="ui-segmented" aria-label="Filter status tugas"><?php foreach (['all'=>['Semua Tugas',$totalTugas],'belum'=>['Belum Selesai',$belumSelesai],'sudah'=>['Sudah Dikumpulkan',$sudahSelesai]] as $key=>[$label,$count]): ?><a href="<?= uiQuery(['filter'=>$key,'page'=>1]) ?>" class="<?= $filter===$key?'active':'' ?>"><?= $label ?> <small>(<?= $count ?>)</small></a><?php endforeach; ?></nav><form method="GET" class="ui-order"><input type="hidden" name="filter" value="<?= e($filter) ?>"><?= uiIcon('info',16) ?><select name="urut" onchange="this.form.requestSubmit()" aria-label="Urutkan tugas"><option value="dekat">Urutkan: Tenggat Terdekat</option><option value="jauh" <?= ($_GET['urut']??'')==='jauh'?'selected':'' ?>>Urutkan: Tenggat Terjauh</option></select></form></div>
 <div class="task-list">
 <?php foreach ($daftarTugas as $task): $submitted=$task['pengumpulan_id']!==null;$graded=$task['nilai']!==null;$urgent=!$submitted && (date('Y-m-d',strtotime($task['batas_pengumpulan']))<=date('Y-m-d',strtotime('+1 day'))); ?>
 <article class="ui-card task-row <?= $graded?'has-grade':'' ?>"><span class="icon-tile <?= $urgent?'rose':(in_array(uiSubjectIcon($task['nama_mapel']),['code','translate'],true)?'aqua':'blue') ?> large"><?= uiIcon(uiSubjectIcon($task['nama_mapel']),24) ?></span><div class="task-copy"><div class="meta-line"><span class="ui-tag <?= uiSubjectIcon($task['nama_mapel'])==='flask'?'aqua':'blue' ?>"><?= e(preg_replace('/ (Wajib|Terapan|& TIK)$/','',$task['nama_mapel'])) ?></span><?php if ($graded): ?><span class="ui-tag aqua"><?= uiIcon('verified',12) ?> Nilai Tersedia</span><?php elseif ($urgent): ?><span class="ui-tag rose"><?= uiIcon('timer',12) ?> <?= isDeadlinePassed($task['batas_pengumpulan'])?'Terlambat':'Mendesak' ?></span><?php endif; ?></div><h2><?= e($task['judul_tugas']) ?></h2><div class="task-meta"><span class="<?= $urgent?'danger':'' ?>"><?= uiIcon('clock',14) ?> Batas Pengumpulan: <?= e(uiShortDate($task['batas_pengumpulan'],true)) ?></span><i>•</i><?php if ($submitted): ?><span><?= uiIcon('history',14) ?> Diserahkan: <?= e(formatTanggalIndo($task['tanggal_kumpul'],'d M Y H:i')) ?></span><?php else: ?><span><?= uiIcon(str_contains(strtolower($task['format_file']),'zip')?'link':(str_contains(strtolower($task['format_file']),'doc')?'file':'paperclip'),14) ?> Format: <?= e(strtoupper($task['format_file'])) ?></span><?php endif; ?><?php if ($task['file_path']): ?><a class="quiet-link" href="download.php?type=tugas&id=<?= (int)$task['id'] ?>"><?= uiIcon('file',14) ?> Lihat Soal</a><?php endif; ?></div></div><div class="task-actions"><?php if ($graded): ?><div class="grade-result"><span><small>Status</small><b>Selesai Dinilai</b></span><strong><?= number_format((float)$task['nilai'],0) ?><small>/100</small></strong></div><a href="lihat_nilai.php?id=<?= (int)$task['id'] ?>" class="ui-button soft"><?= uiIcon('eye',16) ?> Lihat Nilai</a><?php elseif ($submitted): ?><span class="ui-badge blue dot">Sudah Dikumpulkan</span><a href="kumpulkan_tugas.php?id=<?= (int)$task['id'] ?>" class="ui-button soft"><?= uiIcon('eye',16) ?> Lihat Pengumpulan</a><?php else: ?><span class="ui-badge lavender"><i class="status-dot red"></i> Belum Dikirim</span><a href="kumpulkan_tugas.php?id=<?= (int)$task['id'] ?>" class="ui-button primary"><?= uiIcon('upload',16) ?> Kumpulkan Tugas</a><?php endif; ?></div></article>
 <?php endforeach; ?><?php if (!$daftarTugas) uiEmpty('Tidak Ada Tugas', 'Tidak ada tugas pada status yang dipilih.'); ?></div>
<?php uiPagination($taskPage,$taskPageCount,$taskResultCount,'tugas'); ?>
</main><?php require __DIR__.'/../ui_end.php'; ?>
